package com.bocsoft.sqleditor.export;
import com.bocsoft.sqleditor.auth.AuthContext;import com.bocsoft.sqleditor.common.ApiException;import com.bocsoft.sqleditor.common.SqlEditorMetrics;import com.bocsoft.sqleditor.config.SqlEditorProperties;import com.bocsoft.sqleditor.datasource.*;import com.bocsoft.sqleditor.execution.*;import com.bocsoft.sqleditor.export.api.SqlExportRequest;import com.bocsoft.sqleditor.history.ExecutionHistoryService;import com.bocsoft.sqleditor.history.persistence.ExecutionHistoryRecord;import java.io.*;import java.sql.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;
@Service public class CsvExportService {private final ExecutionHistoryService history;private final TargetConnectionProvider targets;private final CsvEncoder csv;private final SqlEditorProperties.Execution limits;private final JdbcValueEncoder values;public CsvExportService(ExecutionHistoryService history,TargetConnectionProvider targets,CsvEncoder csv,SqlEditorProperties properties,JdbcValueEncoder values){this.history=history;this.targets=targets;this.csv=csv;this.limits=properties.getExecution();this.values=values;}
 public PreparedExport prepare(AuthContext auth,SqlExportRequest request,String requestId){ExecutionHistoryRecord original=history.owned(request.getExecutionId(),auth.getUserId());if(original==null)throw new ApiException(HttpStatus.NOT_FOUND,"EXECUTION_NOT_FOUND","执行不存在");if(!"SUCCESS".equals(original.getStatus())||!"RESULT_SET".equals(original.getResultKind()))throw new ApiException(HttpStatus.BAD_REQUEST,"SQL_NOT_EXPORTABLE","该执行结果不可导出");int rowLimit=request.getRowLimit()==null?limits.getMaxRowLimit():request.getRowLimit();if(rowLimit<1||rowLimit>limits.getMaxRowLimit())throw ApiException.validation("rowLimit","OUT_OF_RANGE","导出行数不合法");SavedDataSource source=targets.require(auth,original.getDataSourceId());String exportId=UUID.randomUUID().toString();ExecutionHistoryRecord             record=history.start(exportId,auth,source,original.getDatabaseName(),"EXPORT",original.getStatementText(),StatementType.valueOf(original.getStatementType()),requestId);String filename=safeName(source.getName())+"-"+safeName(original.getDatabaseName()==null?"database":original.getDatabaseName())+".csv";StreamingResponseBody body=out->stream(out,source,original,record,rowLimit);return new PreparedExport(filename,body);}
 private void stream(OutputStream out,SavedDataSource source,ExecutionHistoryRecord original,ExecutionHistoryRecord record,int rowLimit)throws IOException{long started=System.nanoTime();Connection c=null;Statement s=null;long rows=0,bytes=3;try{c=targets.borrow(source);com.bocsoft.sqleditor.engine.EngineSupport engine=targets.engine(source);if(original.getDatabaseName()!=null)engine.applyNamespace(c,original.getDatabaseName());s=c.createStatement(ResultSet.TYPE_FORWARD_ONLY,ResultSet.CONCUR_READ_ONLY);s.setFetchSize(Integer.MIN_VALUE);s.setQueryTimeout(limits.getTimeoutSeconds());s.setMaxRows(rowLimit);if(!s.execute(original.getStatementText()))throw new SQLException("导出 SQL 未返回结果集");csv.bom(out);try(ResultSet rs=s.getResultSet()){ResultSetMetaData meta=rs.getMetaData();List<String>header=new ArrayList<String>();for(int i=1;i<=meta.getColumnCount();i++)header.add(meta.getColumnLabel(i));bytes+=csv.record(out,header);while(rs.next()&&rows<rowLimit){List<Object>row=new ArrayList<Object>();for(int i=1;i<=meta.getColumnCount();i++){Object v=values.encode(rs,i,meta.getColumnType(i));if(v instanceof com.bocsoft.sqleditor.execution.api.BinaryValue)v="[BINARY "+((com.bocsoft.sqleditor.execution.api.BinaryValue)v).getSize()+" bytes]";row.add(v);}long written=csv.record(out,row);bytes+=written;if(bytes>limits.getMaxResultBytes())throw new IOException("导出结果超过大小上限");rows++;if(rows%100==0)out.flush();}}history.success(record,"RESULT_SET",rows,null,rows>=rowLimit,elapsed(started));}catch(SQLException e){history.failure(record,"FAILED",elapsed(started),e);throw new IOException("CSV 导出失败");}catch(IOException e){try{if(s!=null)s.cancel();}catch(SQLException ignored){}history.failure(record,"CANCELLED",elapsed(started),new SQLException("导出中断"));throw e;}finally{if(s!=null)try{s.close();}catch(SQLException ignored){}if(c!=null)try{targets.release(source,c);}catch(SQLException ignored){}}}
 private long elapsed(long n){return Math.max(0,(System.nanoTime()-n)/1000000L);}private String safeName(String v){String x=v.replaceAll("[^A-Za-z0-9._-]+","-");return x.isEmpty()?"export":x;}public static class PreparedExport{private final String filename;private final StreamingResponseBody body;PreparedExport(String f,StreamingResponseBody b){filename=f;body=b;}public String getFilename(){return filename;}public StreamingResponseBody getBody(){return body;}}}
